  "settings.appearance.desc": "Wähle ein Design für die gesamte App — umfasst Topnav, Seitenleiste, Karten und Akzente. Änderungen werden sofort angewendet.",
  "settings.accent.desc": "Färbe Schaltflächen, Links und aktive Zustände ein, ohne dein Design zu verlieren. Wird beim Zurücksetzen auf den integrierten Akzent zurückgesetzt.",
  "settings.integrations.desc": "Verbinde externe Shop-Konten, um deine gekauften Spiele, Spielzeiten und Erfolge in GameIndex zu importieren.",
  "settings.rockstar.desc": "Scanne installierte Spiele des Rockstar Games Launchers (GTA, Red Dead, Max Payne & mehr) und starte sie über den Rockstar-Client. Kein Konto erforderlich.",
  "settings.rockstar.detected": "Rockstar Games Launcher erkannt",
