  "settings.autoSync.desc": "Wie oft GameIndex deine Bibliothek im Hintergrund von Steam, Epic und GOG neu importiert.",
  "settings.historyRetention.desc": "Wie lange historische Steam-Spielerzahlen für die Trend-Sparklines auf jeder Spielseite gespeichert werden. Kürzer = weniger Speicherplatz; länger = detailliertere Kurven.",
  "settings.achievements.noSpoilersTitle": "Erfolgsfortschritt ausblenden (keine Spoiler)",
  "settings.achievements.noSpoilersDesc": "Entfernt globale Freischaltprozente und Seltenheitsringe von der Erfolge-Registerkarte und der Spielseite, damit Erfolgslisten wie eine saubere Checkliste wirken.",
  "settings.achievements.localTitle": "Erfolge für heruntergeladene / gecrackte Spiele verfolgen",
  "settings.achievements.localDesc": "Überwacht lokale Erfolgskonfigurationen von Cracks & Emulatoren (Goldberg, CODEX, RUNE, OnlineFix u.v.m.) und schaltet Erfolge für Nicht-Steam-Spiele frei. Erfolgsdetails werden anonym abgerufen.",
  "settings.discord.title": "Zeigen, was du spielst, auf Discord",
  "settings.discord.desc": "Veröffentlicht einen „Spielt X“-Status in deinem Discord-Profil und entfernt ihn beim Beenden des Spiels.",
  "settings.downloads.notifyDesc": "Lasse dich benachrichtigen, wenn ein Download abgeschlossen ist, damit Übertragungen im Hintergrund laufen können.",
  "settings.downloads.bandwidthDesc": "Steuere die maximale Geschwindigkeit beim Herunterladen und Hochladen von Spiel-Torrents.",
