  "settings.downloads.blockedDesc": "Hier aufgelistete Domains werden aus jeder Download-Suche herausgefiltert — nichts von diesen Hosts erscheint in der Ergebnisliste des Download-Modals. Eine Domain pro Zeile.",
  "settings.downloads.sourcesDescStart": "Füge JSON-formatierte Quell-URLs hinzu, um Download-Spiegelserver für deine Spiele zu finden. Quellen verwenden ein kompatibles JSON-Format mit einem",
  "settings.downloads.sourcesDescEnd": "Array und sind registriert. Die Download-Schaltfläche auf jeder Spielseite durchsucht deine aktivierten Quellen.",
  "settings.downloads.debridDesc": "Konfiguriere einen Debrid-Dienst (AllDebrid oder TorBox), um Torrent-Magnet-Links über schnelle direkte HTTP-Verbindungen herunterzuladen.",
